class Solution {
    Map<Integer,Integer> parent = new HashMap<>();
    Map<Integer,Integer> size = new HashMap<>();
    int find(int x) {
        int root = x;
        while (parent.get(root) != root) root = parent.get(root);
        while (parent.get(x) != x) {
            int nxt = parent.get(x);
            parent.put(x, root);
            x = nxt;
        }
        return root;
    }
    void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size.get(ra) < size.get(rb)) { int t = ra; ra = rb; rb = t; }
        parent.put(rb, ra);
        size.put(ra, size.get(ra) + size.get(rb));
    }
    public int longestConsecutive(int[] nums) {
        if (nums.length == 0) return 0;
        parent.clear(); size.clear();
        for (int n : nums) {
            if (!parent.containsKey(n)) {
                parent.put(n, n);
                size.put(n, 1);
            }
        }
        for (int n : new HashSet<>(parent.keySet())) {
            if (parent.containsKey(n + 1)) union(n, n + 1);
        }
        int ans = 0;
        for (int v : size.values()) ans = Math.max(ans, v);
        return ans;
    }
}
